function nearestSeats(lostSeats,free,rows){const rowIndex=Object.fromEntries(rows.map((r,i)=>[r,i])),picked=[];for(const lost of lostSeats){const p=seatParts(lost);let best=null,score=Infinity;for(const seat of free){if(picked.includes(seat))continue;const q=seatParts(seat),s=Math.abs(q.n-p.n)+Math.abs((rowIndex[q.row]??99)-(rowIndex[p.row]??99))*3;if(s<score){best=seat;score=s}}if(best)picked.push(best)}return picked}

